    'h_postgres' = '\u0442\u0430\u043a\u0436\u0435 \u0443\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 PostgreSQL (\u043f\u0430\u0440\u043e\u043b\u044c \u0440\u043e\u043b\u0438 postgres \u0441\u043e\u0437\u0434\u0430\u0451\u0442\u0441\u044f \u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u0432 \u043f\u0430\u043d\u0435\u043b\u0438)'
    'h_waf' = '\u0440\u0430\u0437\u0432\u0451\u0440\u0442\u044b\u0432\u0430\u0435\u0442 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 WAF \u043f\u0435\u0440\u0435\u0434 \u0441\u0430\u0439\u0442\u0430\u043c\u0438 \u0441 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u043e\u0439:'
    'h_waf2' = 'toutwaf = WAF \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0447\u0438\u043a\u0430 (\u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0449\u0438\u043a, \u0441\u043b\u0443\u0436\u0431\u044b systemd, \u043a\u043e\u043d\u0441\u043e\u043b\u044c :9443); bunkerweb / safeline = \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u044b Docker'
