    'need_root' = '\u064a\u062c\u0628 \u062a\u0634\u063a\u064a\u0644 \u0647\u0630\u0627 \u0627\u0644\u0633\u0643\u0631\u0628\u062a \u0628\u0635\u0644\u0627\u062d\u064a\u0627\u062a root (sudo).'
