    'h_postgres' = '\u064a\u062b\u0628\u062a \u0623\u064a\u0636\u064b\u0627 PostgreSQL (\u062a\u064f\u0646\u0634\u0623 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u062f\u0648\u0631 postgres \u0648\u062a\u064f\u062d\u0641\u0638 \u0641\u064a \u0627\u0644\u0644\u0648\u062d\u0629)'
    'h_waf' = '\u064a\u0646\u0634\u0631 \u062c\u062f\u0627\u0631 \u062d\u0645\u0627\u064a\u0629 \u062a\u0637\u0628\u064a\u0642\u0627\u062a (WAF) \u062e\u0627\u0631\u062c\u064a\u064b\u0627 \u0623\u0645\u0627\u0645 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0645\u0639 \u0625\u0639\u062f\u0627\u062f \u062a\u0644\u0642\u0627\u0626\u064a:'
    'h_waf2' = 'toutwaf = WAF \u0627\u0644\u0646\u0627\u0634\u0631 (\u0627\u0644\u0645\u062b\u0628\u062a \u0627\u0644\u0631\u0633\u0645\u064a\u060c \u062e\u062f\u0645\u0627\u062a systemd\u060c \u0627\u0644\u0648\u0627\u062c\u0647\u0629 :9443)\u061b bunkerweb / safeline = \u062d\u0627\u0648\u064a\u0627\u062a Docker'
    'h_node' = '\u0648\u0636\u0639 \u0627\u0644\u0639\u0642\u062f\u0629 (\u062e\u0648\u0627\u062f\u0645 \u0645\u062a\u0639\u062f\u062f\u0629): \u062a\u0641\u0639\u064a\u0644 HTTPS \u0644\u0644\u0648\u062d\u0629 \u0648\u0625\u0646\u0634\u0627\u0621 \u0631\u0645\u0632 \u062a\u0633\u062c\u064a\u0644 \u0648\u0639\u0631\u0636\u0647 (\u064a\u064f\u062f\u062e\u0644 \u0641\u064a \u0627\u0644\u0644\u0648\u062d\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629: \u0627\u0644\u0646\u0638\u0627\u0645 \u2192 \u0627\u0644\u062e\u0648\u0627\u062f\u0645 \u2192 \u0625\u0636\u0627\u0641\u0629)'
    'h_master' = '\u0645\u0639 --node: \u0639\u0646\u0648\u0627\u0646 URL \u0644\u0644\u0648\u062d\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 (\u064a\u064f\u0639\u0631\u0636 \u0644\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u062f\u064a\u0631\u0647\u0627)'
    'h_username' = '\u0627\u0633\u0645 \u062d\u0633\u0627\u0628 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 (\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a: \u0639\u0634\u0648\u0627\u0626\u064a)'
    'h_password' = '\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 (\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a: \u0639\u0634\u0648\u0627\u0626\u064a\u0629\u061b \u062a\u0638\u0647\u0631 \u0641\u064a \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0648\u0627\u0644\u0633\u062c\u0644: \u064a\u064f\u0641\u0636\u064e\u0651\u0644 \u0627\u0644\u0645\u062a\u063a\u064a\u0631 \u0623\u0648 \u0645\u0644\u0641 \u0623\u0648 \u0627\u0644\u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0642\u064a\u0627\u0633\u064a \u0623\u062f\u0646\u0627\u0647)'
    'h_entrance' = '\u0627\u0644\u0645\u062f\u062e\u0644 \u0627\u0644\u0622\u0645\u0646 (\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a: \u0639\u0634\u0648\u0627\u0626\u064a)'
    'h_source' = '\u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0645\u0646 \u0645\u0633\u062a\u0648\u062f\u0639 \u0645\u062d\u0644\u064a: \u0627\u0644\u0634\u064a\u0641\u0631\u0629 \u0627\u0644\u0645\u0635\u062f\u0631\u064a\u0629 (pyproject.toml\u060c \u0645\u0633\u062a\u0648\u062f\u0639 \u0627\u0644\u062a\u0637\u0648\u064a\u0631) \u0623\u0648 \u062d\u0632\u0645 wheel \u0645\u064f\u062c\u0645\u0651\u0639\u0629 \u0645\u0633\u0628\u0642\u064b\u0627 (\u0645\u062c\u0644\u062f dist\u060c \u0646\u0633\u062e\u0629 \u0645\u0646 \u0627\u0644\u0645\u0633\u062a\u0648\u062f\u0639 \u0627\u0644\u0639\u0627\u0645)'
    'h_branch' = '\u0641\u0631\u0639 git \u0627\u0644\u0645\u0631\u0627\u062f \u062a\u0646\u0632\u064a\u0644\u0647 (\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a: main)'
    'h_channel' = '\u0642\u0646\u0627\u0629 \u0627\u0644\u062a\u062d\u062f\u064a\u062b: stable (\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u060c \u0627\u0644\u0641\u0631\u0639 main / \u0627\u0644\u0625\u0635\u062f\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0648\u0633\u0648\u0645\u0629) \u0623\u0648 dev (\u0627\u0644\u0641\u0631\u0639 dev\u060c \u0625\u0635\u062f\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0637\u0648\u064a\u0631)\u061b \u062a\u064f\u062d\u0641\u0638 \u0641\u064a \u0627\u0644\u0644\u0648\u062d\u0629 (\u0627\u0644\u062a\u062d\u062f\u064a\u062b\u0627\u062a \u2192 \u0644\u0648\u062d\u0629 \u0627\u0644\u062a\u062d\u0643\u0645)'
    'h_update' = '\u064a\u062d\u062f\u0651\u062b \u062a\u062b\u0628\u064a\u062a\u064b\u0627 \u0645\u0648\u062c\u0648\u062f\u064b\u0627 (\u064a\u064f\u0643\u062a\u0634\u0641 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627): \u0646\u0633\u062e \u0627\u062d\u062a\u064a\u0627\u0637\u064a \u0644\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u060c \u0634\u064a\u0641\u0631\u0629 \u062c\u062f\u064a\u062f\u0629\u060c \u062a\u0631\u062d\u064a\u0644 \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u060c \u0625\u0639\u0627\u062f\u0629 \u062a\u0634\u063a\u064a\u0644\u061b \u0645\u0639 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0648\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0648\u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0648\u0627\u0644\u0628\u0631\u0627\u0645\u062c. \u0623\u0636\u0641 --stack / --mail / --waf \u0644\u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u062d\u0632\u0645\u0629.'
    'h_update_win' = '\u064a\u062d\u062f\u0651\u062b \u062a\u062b\u0628\u064a\u062a\u064b\u0627 \u0645\u0648\u062c\u0648\u062f\u064b\u0627 (\u064a\u064f\u0643\u062a\u0634\u0641 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627): \u0646\u0633\u062e \u0627\u062d\u062a\u064a\u0627\u0637\u064a \u0644\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u060c \u0634\u064a\u0641\u0631\u0629 \u062c\u062f\u064a\u062f\u0629\u060c \u062a\u0631\u062d\u064a\u0644 \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u060c \u0625\u0639\u0627\u062f\u0629 \u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0645\u0647\u0645\u0629\u061b \u0645\u0639 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0648\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a'
    'h_reinstall' = '\u064a\u0641\u0631\u0636 \u062a\u062b\u0628\u064a\u062a\u064b\u0627 \u0643\u0627\u0645\u0644\u064b\u0627 \u062d\u062a\u0649 \u0644\u0648 \u0643\u0627\u0646\u062a \u0627\u0644\u0644\u0648\u062d\u0629 \u0645\u0648\u062c\u0648\u062f\u0629'
    'h_uninstall' = '\u064a\u0632\u064a\u0644 \u0627\u0644\u0644\u0648\u062d\u0629 (\u0627\u0644\u062e\u062f\u0645\u0629\u060c \u0645\u0644\u0641\u0627\u062a \u0627\u0644\u0644\u0648\u062d\u0629\u060c \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u064f\u0646\u0634\u0623\u0629)\u061b \u0645\u0639 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u0645\u0648\u0627\u0642\u0639 (/www/wwwroot) \u0648\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0623\u0631\u0634\u0641\u0629 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0644\u0648\u062d\u0629'
    'h_uninstall_win' = '\u064a\u0632\u064a\u0644 \u0627\u0644\u0644\u0648\u062d\u0629 (\u0627\u0644\u0645\u0647\u0627\u0645 \u0627\u0644\u0645\u062c\u062f\u0648\u0644\u0629\u060c \u0645\u062c\u0644\u062f \u0627\u0644\u0644\u0648\u062d\u0629)\u061b \u062a\u0628\u0642\u0649 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0648\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0643\u0645\u0627 \u0647\u064a \u0648\u062a\u064f\u0624\u0631\u0634\u0641 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0644\u0648\u062d\u0629 \u0641\u064a \u0645\u0644\u0641 zip'
    'h_yes' = '\u0644\u0627 \u064a\u0637\u0631\u062d \u0623\u064a \u0633\u0624\u0627\u0644 (\u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0648\u0627\u0644\u062a\u0623\u0643\u064a\u062f\u0627\u062a): \u0644\u0644\u062a\u062b\u0628\u064a\u062a \u0627\u0644\u0622\u0644\u064a'
    'h_stack_win' = '\u064a\u062b\u0628\u062a \u0623\u064a\u0636\u064b\u0627 Nginx (nginx.org) \u0648PHP 8.3 (windows.php.net\u060c \u062a\u062f\u064a\u0631\u0647 \u0627\u0644\u0644\u0648\u062d\u0629) \u0648MariaDB (\u062d\u0632\u0645\u0629 MSI \u0627\u0644\u0631\u0633\u0645\u064a\u0629\u060c \u062e\u062f\u0645\u0629 Windows)'
    'h_lang' = '\u0644\u063a\u0629 \u0627\u0644\u0645\u062b\u0628\u062a \u0648\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0648\u0644\u064a\u0629 \u0644\u0644\u0648\u062d\u0629: en fr de es it pt nl ru zh ar'
    'h_lang_short' = '\u0627\u062e\u062a\u0635\u0627\u0631\u0627\u062a \u062e\u064a\u0627\u0631 \u0627\u0644\u0644\u063a\u0629'
